test('random interleavings keep the invariant', async () => {
  let seed = 42;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 300; run++) {
    const h = await createHost();
    const ids = ['a', 'b', 'c', 'd'];
    for (let step = 0; step < 30; step++) {
      const k = rnd(5);
      const id = ids[rnd(ids.length)];
      if (k === 4) await h.expire(id);
      else if (k === 0) await h.place(id, 1 + rnd(2));
      else if (k === 1) await h.cancel(id);
      else if (k === 2) await h.restock();
      else {
        const msgs = await h.inFlight();
        if (msgs.length) await h.deliver(msgs[rnd(msgs.length)].id);
      }
      const s = await h.stock();
      assert.ok(s.available >= 0 && s.reserved >= 0 && s.available + s.reserved <= 3);
      for (const i of ids) {
        const o = await h.order(i);
        if (o?.status === 'confirmed') assert.ok(s.reserved >= o.qty);
      }
    }
    await h.deliverAll();
    const s = await h.stock();
    let confirmed = 0;
    for (const i of ids) {
      const o = await h.order(i);
      assert.notEqual(o?.status, 'pending');
      assert.notEqual(o?.status, 'cancelling');
      if (o?.status === 'confirmed') confirmed += o.qty;
    }
    assert.equal(s.reserved, confirmed);
  }
});

