      }
      const s = await h.stock();
      assert.ok(s.available >= 0 && s.reserved >= 0 && s.available + s.reserved <= 3);
      for (const i of ids) {
        const o = await h.order(i);
        if (o?.status === 'confirmed') assert.ok(s.reserved >= o.qty);
      }
    }
    await h.deliverAll();
    const s = await h.stock();
    let confirmed = 0;
    for (const i of ids) {
      const o = await h.order(i);
      assert.notEqual(o?.status, 'pending');
      assert.notEqual(o?.status, 'cancelling');
      if (o?.status === 'confirmed') confirmed += o.qty;
    }
    assert.equal(s.reserved, confirmed);
  }
});

